code_example:
#include <iostream>
#include <vector>

class Buffer {
public:
    int* data;
    size_t size;
    // Constructor
    Buffer(size_t s) : data(new int[s]), size(s) {
        std::cout << "Constructed" << std::endl;
    }
    // Destructor
    ~Buffer() { delete[] data; }
    // Move constructor
    Buffer(Buffer&& other) noexcept : data(other.data), size(other.size) {
        other.data = nullptr;
        other.size = 0;
        std::cout << "Moved" << std::endl;
    }
    // Move assignment
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            size = other.size;
            other.data = nullptr;
            other.size = 0;
            std::cout << "Move assigned" << std::endl;
        }
        return *this;
    }
    // Disable copy semantics
    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;
};

int main() {
    Buffer buf1(10);
    Buffer buf2 = std::move(buf1); // Move constructor invoked
    std::cout << "buf1 data pointer: " << buf1.data << std::endl;
    std::cout << "buf2 data pointer: " << buf2.data << std::endl;
    return 0;
}
